use std::collections::HashMap;

// #[derive(...)] asks the compiler to write standard trait code for us:
// Clone and Copy let us copy a Direction freely, PartialEq lets us compare with ==,
// and Eq and Hash let us use a Direction as a HashMap key.
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
enum Direction {
    North,
    South,
    West,
}

enum Command {
    Look,
    Go(Direction),
    Take,
    Unknown(String),
}

#[derive(PartialEq)]   // needed for `game.state == State::Won` in main
enum State {
    Playing,
    Won,
}

struct Room {
    description: &'static str,
    exits: HashMap<Direction, &'static str>,
    item: Option<&'static str>,
}

struct Game {
    rooms: HashMap<&'static str, Room>,
    current: &'static str,
    inventory: Vec<&'static str>,
    state: State,
}

fn parse(input: &str) -> Command {
    let mut words = input.split_whitespace();
    let verb = words.next().unwrap_or("");
    let target = words.next().unwrap_or("");
    // Match on both words at once. `_` means "any value here".
    match (verb, target) {
        ("look", _) => Command::Look,
        ("go", "north") => Command::Go(Direction::North),
        ("go", "south") => Command::Go(Direction::South),
        ("go", "west") => Command::Go(Direction::West),
        ("take", _) => Command::Take,
        _ => Command::Unknown(input.to_string()),
    }
}

impl Game {
    fn new() -> Game {
        let mut rooms = HashMap::new();
        rooms.insert("hall", Room {
            description: "a dusty hall with doors north and west",
            // HashMap::from builds a map from (key, value) pairs
            exits: HashMap::from([
                (Direction::North, "library"),
                (Direction::West, "vault"),
            ]),
            item: None,
        });
        rooms.insert("library", Room {
            description: "a quiet library",
            exits: HashMap::from([(Direction::South, "hall")]),
            item: Some("key"),
        });
        rooms.insert("vault", Room { description: "a vault full of gold", exits: HashMap::new(), item: None });
        Game { rooms, current: "hall", inventory: Vec::new(), state: State::Playing }
    }

    fn step(&mut self, command: Command) -> String {
        match command {
            Command::Look => {
                let room = &self.rooms[self.current];
                let mut text = format!("You are in {}.", room.description);
                if let Some(item) = room.item {
                    text.push_str(&format!(" You see a {item}."));
                }
                text
            }
            Command::Go(direction) => {
                let target = match self.rooms[self.current].exits.get(&direction) {
                    Some(name) => *name,   // get returns a reference; * copies the &str out
                    None => return String::from("You can't go that way."),
                };
                // contains(&"key") asks whether the Vec holds that text
                if target == "vault" && !self.inventory.contains(&"key") {
                    return String::from("The vault door is locked. Maybe a key would help.");
                }
                self.current = target;
                if target == "vault" {
                    self.state = State::Won;
                    return String::from("You unlock the vault with the key. You win!");
                }
                format!("You walk to the {target}.")
            }
            Command::Take => {
                // get_mut: a mutable reference to the room (current always names one)
                let room = self.rooms.get_mut(self.current).unwrap();
                // take() empties room.item and hands back what was there
                match room.item.take() {
                    Some(item) => {
                        self.inventory.push(item);
                        format!("You take the {item}.")
                    }
                    None => String::from("There is nothing to take."),
                }
            }
            Command::Unknown(text) => format!("I don't understand '{text}'."),
        }
    }
}

fn main() {
    let script = [
        "look", "go west", "go north", "look", "take", "take",
        "dance", "go south", "go west", "look",
    ];
    let mut game = Game::new();
    for line in script {
        if game.state == State::Won {
            println!("(the game is over)");
            break;
        }
        println!("> {line}");
        println!("{}", game.step(parse(line)));
    }
}

// Output:
// > look
// You are in a dusty hall with doors north and west.
// > go west
// The vault door is locked. Maybe a key would help.
// > go north
// You walk to the library.
// > look
// You are in a quiet library. You see a key.
// > take
// You take the key.
// > take
// There is nothing to take.
// > dance
// I don't understand 'dance'.
// > go south
// You walk to the hall.
// > go west
// You unlock the vault with the key. You win!
// (the game is over)

exercise.starter:
enum Command {
    Look,
    Inventory,
    Unknown(String),
}

fn parse(input: &str) -> Command {
    match input {
        "look" => Command::Look,
        // Until you add the arm for inventory, Command::Inventory is never created,
        // so the compiler warns about it. The warning goes away when you are done.
        _ => Command::Unknown(input.to_string()),
    }
}

fn main() {
    let inventory = ["key", "lamp"];
    for input in ["look", "i", "dance"] {
        match parse(input) {
            Command::Look => println!("You see a dusty hall."),
            Command::Inventory => println!("You carry: {}", inventory.join(", ")),
            Command::Unknown(text) => println!("I don't understand '{text}'."),
        }
    }
}

